	@Override
	public ResponseEntity<ValidationRes> checkLoginId(ValidationRequest req) throws Exception{
		
		ValidationRes res = new ValidationRes();
//		List<Error> error = new ArrayList<>();


		if (null == req || StringUtils.isBlank( req.getType()) ) {
			
			return new ResponseEntity<ValidationRes>(res, HttpStatus.BAD_REQUEST);
			
		}
		if (req.getType().equalsIgnoreCase("LOGIN_ID_CHECK")) {

			if (StringUtils.isNotBlank(req.getLoginId())) {

				LoginMaster loginData = loginRepo.findByLoginId(req.getLoginId());	

					if (null == loginData) {
						res.setMessage("Login Id Is Not Exists");
						res.setIsError(true);					
						return new ResponseEntity<ValidationRes>(res, HttpStatus.OK);

					} else {

						res.setMessage("Login Id Already Exists");
						res.setIsError(false);
						return new ResponseEntity<ValidationRes>(res, HttpStatus.OK);

					}

			}else {
				
				return new ResponseEntity<ValidationRes>(res, HttpStatus.BAD_REQUEST);

			}

		} else if (req.getType().equalsIgnoreCase("LOGIN_ID_DATA")) {
			
			LoginDataValidationRes result = new LoginDataValidationRes();
			
			
			if (StringUtils.isNotBlank(req.getLoginId())) {
				LoginMaster loginData = loginRepo.findByLoginId(req.getLoginId());

				if (null != loginData) {
					res.setMessage("SUCCESS");
					res.setIsError(false);
					result.setLoginId(StringUtils.isNotBlank(loginData.getLoginId()) ? loginData.getLoginId() : "");
					result.setSubUserType(
							StringUtils.isNotBlank(loginData.getSubUserType()) ? loginData.getSubUserType() : "");
					result.setUserType(StringUtils.isNotBlank(loginData.getUserType()) ? loginData.getUserType() : "");
					result.setAgencyCode(
							StringUtils.isNotBlank(loginData.getAgencyCode()) ? loginData.getAgencyCode() : "");
					result.setZone("01");
					List<LoginBranchMaster> brancheList = lbranchRepo
							.findByLoginIdOrderByUpdatedDateDesc(req.getLoginId());
					String branchCode = null;

					if (null != brancheList && !brancheList.isEmpty()) {

						List<String> brokerBranchCodeList = brancheList.stream().map(a -> a.getBrokerBranchCode())
								.collect(Collectors.toList());

						result.setBrokerBranchCode(brokerBranchCodeList);

						if (null != brokerBranchCodeList && !brokerBranchCodeList.isEmpty()) {

							branchCode = brokerBranchCodeList.get(0);
						}
					}

					result.setBrokerCode(
							StringUtils.isNotBlank(loginData.getAgencyCode()) ? loginData.getAgencyCode() : "");
					
					String companyId = StringUtils.isNotBlank(loginData.getCompanyId() ) ? loginData.getCompanyId() : "";

					List<ListItemValue> sourceList = getListItem(branchCode, "SOURCE_TYPE", companyId );

					if (null != sourceList && !sourceList.isEmpty()) {

						result.setSource(sourceList.stream().collect(Collectors.toMap(a -> a.getItemCode(),
								a -> a.getItemValue(), (oldData, newData) -> newData)));
					}

					LoginUserInfo loginUserInfoList = loginUserInfoRepo.findByLoginId(
							StringUtils.isNotBlank(loginData.getLoginId()) ? loginData.getLoginId() : "");

					if (null != loginUserInfoList) {

						result.setBdmCode(StringUtils.isNotBlank(loginUserInfoList.getCustomerCode()) ? loginUserInfoList.getCustomerCode() :							
							StringUtils.isNotBlank(loginUserInfoList.getOaCode()) ? loginUserInfoList.getOaCode() : ""	 );
								
					}
					res.setResult(result);
					return new ResponseEntity<ValidationRes>(res, HttpStatus.OK);

				} else {

					res.setMessage("No Data Found For This LoginId");
					res.setIsError(true);
					return new ResponseEntity<ValidationRes>(res, HttpStatus.OK);

				}

			} else {

				return new ResponseEntity<ValidationRes>(res, HttpStatus.BAD_REQUEST);

			}

		} 
		else if(req.getType().equalsIgnoreCase("SEAT_CAPACITY") ) {
			
			if (StringUtils.isBlank(req.getInsuranceId()) || StringUtils.isBlank(req.getBranchCode())
					|| StringUtils.isBlank(req.getBodyType()) || null == req.getSeatingCapacity()) {

				return new ResponseEntity<ValidationRes>(res, HttpStatus.BAD_REQUEST);

			}
			
			boolean isError = false;
	 		
		  Map<String, Integer> SeatingCapacityMap = new HashMap<>();
			 
			
			if (StringUtils.isBlank(req.getSeatingCapacity())) {
				// error.add(new Error("18", "SeatingCapacity" , "Please Enter Seating Capacity"));
				res.setMessage("Please Enter Seating Capacity");
				res.setIsError(true);
				isError = true;
				
			 } else if (! req.getSeatingCapacity().matches("[0-9]+") ) {
				// error.add( new Error("14", "SeatingCapacity" , "Please Enter Valid Number in Seating Capacity"));
				 res.setMessage("Please Enter Valid Number in Seating Capacity");
				 res.setIsError(true);
				 isError = true;
				 
			 } else if(StringUtils.isNotBlank(req.getInsuranceId()) && StringUtils.isNotBlank(req.getBranchCode()) && StringUtils.isNotBlank(req.getBodyType()) ) {
					  
				// List<MotorBodyTypeMaster> bodyTypes =  regulatory.getInduvidualBodyTypeMasterDropdown(req.getInsuranceId() ,req.getBranchCode() , req.getBodyType() ) ;
				
				 Date today = new Date(); 
				Integer bodyId = StringUtils.isNotBlank( req.getBodyType()) ?  Integer.valueOf(req.getBodyType()) : 0 ;
				 
				 List<MotorBodyTypeMaster> bodyTypes =	 motorBodyTypeRepo.findAllByCompanyIdAndBranchCodeAndBodyIdAndEffectiveDateStartLessThanEqualAndEffectiveDateEndGreaterThan(
						 req.getInsuranceId() , "99999" , bodyId , today , today);
				 
				 if (Integer.valueOf(req.getSeatingCapacity().toString() ) <= 0 ) {
				
					// error.add( new Error("09", "SeatingCapacity" , "Seating Capacity 0 not allowed "));
					 res.setMessage("Seating Capacity 0 not allowed");
					 res.setIsError(true);
					 isError = true;
				 }
				 else  if( bodyTypes.size() > 0 && bodyTypes.get(0).getSeatingCapacity() !=null && bodyTypes.get(0).getSeatingCapacity()  < Integer.valueOf(req.getSeatingCapacity())   )  {
					
					 //error.add( new Error("09", "SeatingCapacity" , "Seating Capacity Must be under " + bodyTypes.get(0).getSeatingCapacity() +  " only allowed "));
					 res.setMessage("Seating capacity should be below " + bodyTypes.get(0).getSeatingCapacity());
					 res.setIsError(true);
					 isError = true;
					 SeatingCapacityMap.put("Seating Capacity", bodyTypes.get(0).getSeatingCapacity());
					 res.setResult(SeatingCapacityMap);
					
				 }
			 }
				if (!isError) {

					res.setMessage("Success");
					res.setIsError(false);
					SeatingCapacityMap.put("Seating Capacity", 0);
					res.setResult(SeatingCapacityMap);
				}
			}

			return new ResponseEntity<ValidationRes>(res, HttpStatus.OK);
		}

		public synchronized List<ListItemValue> getListItem(String branchCode , String itemType, String companyId) {
			List<ListItemValue> list = new ArrayList<ListItemValue>();
			try {
				Date today = new Date();
				Calendar cal = new GregorianCalendar();
				cal.setTime(today);
				today = cal.getTime();
				Date todayEnd = cal.getTime();
				
				// Criteria
				CriteriaBuilder cb = em.getCriteriaBuilder();
				CriteriaQuery<ListItemValue> query=  cb.createQuery(ListItemValue.class);
				// Find All
				Root<ListItemValue> c = query.from(ListItemValue.class);
				
				//Select
				query.select(c);
				// Order By
				List<Order> orderList = new ArrayList<Order>();
				orderList.add(cb.asc(c.get("branchCode")));
				
				
				// Effective Date Start Max Filter
				Subquery<Long> effectiveDate = query.subquery(Long.class);
				Root<ListItemValue> ocpm1 = effectiveDate.from(ListItemValue.class);
				effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
				Predicate a1 = cb.equal(c.get("itemId"),ocpm1.get("itemId"));
				Predicate a2 = cb.lessThanOrEqualTo(ocpm1.get("effectiveDateStart"), today);
				Predicate b1= cb.equal(c.get("branchCode"),ocpm1.get("branchCode"));
				Predicate b2 = cb.equal(c.get("companyId"),ocpm1.get("companyId"));
				effectiveDate.where(a1,a2,b1,b2);
				
				// Effective Date End Max Filter
				Subquery<Long> effectiveDate2 = query.subquery(Long.class);
				Root<ListItemValue> ocpm2 = effectiveDate2.from(ListItemValue.class);
				effectiveDate2.select(cb.max(ocpm2.get("effectiveDateEnd")));
				Predicate a3 = cb.equal(c.get("itemId"),ocpm2.get("itemId"));
				Predicate a4 = cb.greaterThanOrEqualTo(ocpm2.get("effectiveDateEnd"), todayEnd);
				Predicate b3= cb.equal(c.get("companyId"),ocpm2.get("companyId"));
				Predicate b4= cb.equal(c.get("branchCode"),ocpm2.get("branchCode"));
				effectiveDate2.where(a3,a4,b3,b4);
							
				// Where
				Predicate n1 = cb.equal(c.get("status"),"Y");
				Predicate n2 = cb.equal(c.get("effectiveDateStart"),effectiveDate);
				Predicate n3 = cb.equal(c.get("effectiveDateEnd"),effectiveDate2);	
				Predicate n4 = cb.equal(c.get("companyId"), companyId);
			//	Predicate n5 = cb.equal(c.get("companyId"), "99999");
				Predicate n6 = cb.equal(c.get("branchCode"), branchCode);
				Predicate n7 = cb.equal(c.get("branchCode"), "99999");
				//Predicate n8 = cb.or(n4,n5);
				Predicate n9 = cb.or(n6,n7);
				Predicate n10 = cb.equal(c.get("itemType"),itemType);
				Predicate n11 = cb.equal(c.get("status"),"R");
				Predicate n12 = cb.or(n1,n11);
			
				query.where(n2,n3,n4,n9,n10,n12).orderBy(orderList);
			

				TypedQuery<ListItemValue> result = em.createQuery(query);
				list = result.getResultList();
				
				
				
			//	list = list.stream().filter(distinctByKey(o -> Arrays.asList(o.getItemCode()))).collect(Collectors.toList());
			//	list = list.stream().sorted((o1, o2)->Long.valueOf(o1.getItemValue()).compareTo(Long.valueOf(o2.getItemValue()))).collect(Collectors.toList());
				list.sort(Comparator.comparing(ListItemValue :: getItemValue));
			} catch (Exception e) {
				e.printStackTrace();
				log.info("Exception is ---> " + e.getMessage());
				return null;
			}
			return list ;
		}
	
